// Names and words for Chronicles, Job, Psalms, Proverbs, Ecclesiastes, Song of Solomon and Lamentations. Checked with audit.js.
// Names and words for Chronicles, Job, Psalms, Proverbs, Ecclesiastes, Song of Solomon and Lamentations, with name meanings.
// Loads after gloss4.js / gloss5.js. Where a meaning is uncertain or unknown, the card says so. Names shared by several people are sorted verse by verse with ALT.
const OT2=(o)=>Object.assign({lang:"Hebrew",books:["ps"],more:[],resp:"",say:"",heb:"",tr:"",strong:""},o);
const OT2ALT=(refs,map)=>refs.forEach(r=>{ALT[r]=Object.assign(ALT[r]||{},map);});

// ---- Existing Genesis/Exodus/Numbers cards whose wording still fits ----
TERMS.gen_adam.books.push("1chr","job");
TERMS.gen_noah.books.push("1chr");
TERMS.gen_shem.books.push("1chr");
TERMS.gen_abraham.books.push("1chr","2chr","ps");
TERMS.gen_isaac.books.push("1chr","2chr","ps");
TERMS.gen_levi.books.push("1chr","ps");
TERMS.gen_edom.books.push("1chr","2chr","ps","lam");
TERMS.gen_manasseh.books.push("1chr","2chr","ps");
TERMS.exo_aaron.books.push("1chr","2chr","ps");
TERMS.num_meribah.books.push("ps");

// ---- New cards ----
Object.assign(TERMS,{
// ================= 1–2 Chronicles: early genealogy =================
ot2_enosh:OT2({name:"Enosh",forms:["Enosh"],resp:"EE-nosh",say:"ee nosh",heb:"אֱנוֹשׁ",tr:"Enosh",strong:"H583",books:["1chr"],
 plain:"Seth’s son and Adam’s grandson, named in the opening line of Chronicles (1:1). The name means “man,” in the sense of frail, mortal humanity; the same Hebrew word is the “man” of Psalm 8:4, “What is man, that thou art mindful of him?”",
 bg:"In his days “began men to call upon the name of the LORD” (Genesis 4:26). Latter-day Saint scripture calls him Enos and says Adam ordained him (D&C 107:44)."}),
ot2_sheth:OT2({name:"Sheth (Seth)",forms:["Sheth"],resp:"SHETH",say:"sheth",heb:"שֵׁת",tr:"Shet",strong:"H8352",books:["1chr"],
 plain:"Adam’s third son named in the opening genealogy (1:1); the KJV spells the name Sheth here and Seth in Genesis. It means “appointed” or “granted”: Eve said, “God … hath appointed me another seed instead of Abel” (Genesis 4:25).",
 bg:"Adam ordained Seth at age 69, and “his likeness was the express likeness of his father” (D&C 107:42–43)."}),
ot2_peleg:OT2({name:"Peleg",forms:["Peleg"],resp:"PEE-leg",say:"pee leg",heb:"פֶּלֶג",tr:"Peleg",strong:"H6389",books:["1chr"],
 plain:"A descendant of Shem and an ancestor of Abraham (1:19, 25). The name means “division” or “channel,” and the text explains it: “in his days the earth was divided” (1:19). What the division was is not stated; many readers link it to the scattering of peoples after Babel.",
 bg:"The same Hebrew word is the “rivers” of Psalm 1:3, “planted by the rivers of water,” since a peleg is a watercourse that divides the land."}),
ot2_perez:OT2({name:"Perez / Pharez",forms:["Perez","Pharez"],resp:"PEE-rez / FAY-rez",say:"pee rez, fay rez",heb:"פֶּרֶץ",tr:"Peretz",strong:"H6557",books:["1chr"],
 plain:"A son of Judah by Tamar and an ancestor of David (2:4–5; 27:3). The name means “breach” or “breaking out”: the midwife said, “How hast thou broken forth? this breach be upon thee: therefore his name was called Pharez” (Genesis 38:29).",
 bg:"Perez stands in the line of Jesus, spelled “Phares” in Matthew 1:3, and the people of Bethlehem blessed Ruth’s marriage, “let thy house be like the house of Pharez” (Ruth 4:12)."}),
ot2_achar:OT2({name:"Achar (Achan)",forms:["Achar"],resp:"AY-kar",say:"ay kar",heb:"עָכָר",tr:"ʿAkhar",strong:"H5917",books:["1chr"],
 plain:"A man of Judah called “the troubler of Israel, who transgressed in the thing accursed” (2:7). The name means “trouble,” and the writer plays on it: Achar is the one who brought trouble. The book of Joshua calls him Achan (Joshua 7), the man who kept loot from Jericho that had been put under the ban.",
 bg:"Joshua said, “Why hast thou troubled us? the LORD shall trouble thee this day,” and the place was named the valley of Achor, “trouble” (Joshua 7:25–26). Hosea promises “the valley of Achor for a door of hope” (Hosea 2:15)."}),
ot2_jabez:OT2({name:"Jabez",forms:["Jabez"],resp:"JAY-bez",say:"jay bez",heb:"יַעְבֵּץ",tr:"Yaʿbets",strong:"H3258",books:["1chr"],
 plain:"A man of Judah “more honourable than his brethren,” whose mother “called his name Jabez, saying, Because I bare him with sorrow” (4:9). The name is a play on the Hebrew word otsev, “pain” or “sorrow,” with its consonants reordered, and his prayer to be kept from evil “that it may not grieve me” (4:10) uses the word again, as if the prayer undoes his name.",
 bg:"“God granted him that which he requested” (4:10)."}),
ot2_jabez_place:OT2({name:"Jabez (the town)",forms:[],resp:"JAY-bez",say:"jay bez",heb:"יַעְבֵּץ",tr:"Yaʿbets",strong:"H3258",books:["1chr"],
 plain:"A place in Judah “where the families of the scribes … dwelt” (2:55). Its location is not known, and the text does not say whether it was named for the man in 4:9 (the name means “sorrow” or “pain”).",
 bg:""}),
ot2_zadok:OT2({name:"Zadok",forms:["Zadok"],resp:"ZAY-dok",say:"zay dock",heb:"צָדוֹק",tr:"Tsadoq",strong:"H6659",books:["1chr","2chr"],
 plain:"A priest of Aaron’s line who served David and then Solomon, and whom Solomon made the chief priest in place of Abiathar (1 Kings 2:35). The name is usually understood to mean “righteous” or “just,” from the root tsdq.",
 bg:"The people anointed Solomon “unto the LORD to be the chief governor, and Zadok to be priest” (1 Chronicles 29:22). The “sons of Zadok” later became the standard name for the rightful priesthood of Jerusalem (Ezekiel 44:15)."}),
ot2_abiathar:OT2({name:"Abiathar",forms:["Abiathar"],resp:"uh-BYE-uh-thar",say:"uh bye uh thar",heb:"אֶבְיָתָר",tr:"Evyatar",strong:"H54",books:["1chr"],
 plain:"The only priest to escape the killing at Nob; he fled to David and served as priest beside Zadok (15:11; 1 Samuel 22:20–23). The name is often explained as “the father is abundant” or “father of abundance,” but the meaning is not certain.",
 bg:"He later backed Adonijah, and Solomon removed him from the priesthood, which fulfilled the word of the LORD about the house of Eli (1 Kings 2:26–27)."}),
ot2_asaph:OT2({name:"Asaph",forms:["Asaph"],resp:"AY-saf",say:"ay saff",heb:"אָסָף",tr:"ʾAsaf",strong:"H623",books:["1chr","2chr","ps"],
 plain:"A Levite appointed by David as a chief singer, who sounded the cymbals before the ark (15:17, 19; 16:5). His family of singers lasted for centuries (2 Chronicles 35:15), and twelve psalms bear his name: Psalm 50 and Psalms 73–83. The name means “he gathers,” from the verb asaph.",
 bg:"The same verb opens the LORD’s call in Asaph’s first psalm: “Gather my saints together unto me” (Psalm 50:5)."}),
ot2_heman:OT2({name:"Heman (the singer)",forms:["Heman"],resp:"HEE-mun",say:"hee mun",heb:"הֵימָן",tr:"Heman",strong:"H1968",books:["1chr","2chr","ps"],
 plain:"A Levite, grandson of the prophet Samuel (6:33–38), who with Asaph and Ethan or Jeduthun led the temple music under David (15:17; 25:1–6). He is called “the king’s seer in the words of God,” and “God gave to Heman fourteen sons and three daughters” (25:5). The name is usually understood to mean “faithful,” though this is not certain.",
 bg:"A different Heman, a wise man of Judah called “the Ezrahite,” is named in 1 Chronicles 2:6 and in the title of Psalm 88; those verses use the Ezrahites card."}),
ot2_ethan:OT2({name:"Ethan (the singer)",forms:["Ethan"],resp:"EE-thun",say:"ee thun",heb:"אֵיתָן",tr:"ʾEitan",strong:"H387",books:["1chr","ps"],
 plain:"A Levite of Merari’s family who, with Heman and Asaph, was appointed to sound the bronze cymbals when the ark was brought up (6:44; 15:17, 19). Another Levite Ethan, an ancestor of Asaph, is named in 6:42. The name means “enduring,” “permanent” or “strong,” and the word is used of ever-flowing rivers.",
 bg:"A different Ethan, “the Ezrahite,” a wise man of Judah, is named in 1 Chronicles 2:6, 8 and in the title of Psalm 89; those verses use the Ezrahites card."}),
ot2_ezrahites:OT2({name:"Ethan and Heman the Ezrahite",forms:[],resp:"EZ-ruh-hite",say:"ez ruh hite",heb:"אֵיתָן / הֵימָן הָאֶזְרָחִי",tr:"ʾEitan / Heman ha-ʾEzrachi",strong:"H387 / H1968",books:["1chr","ps"],
 plain:"Wise men of Judah, named among “the sons of Zerah” (1 Chronicles 2:6), whose wisdom Solomon surpassed: “wiser than all men; than Ethan the Ezrahite, and Heman, and Chalcol, and Darda” (1 Kings 4:31). Psalm 88 is headed “Heman the Ezrahite” and Psalm 89 “Ethan the Ezrahite.” Ethan is usually understood to mean “enduring” and Heman “faithful.”",
 bg:"Whether these are the same men as the Levite singers of the same names is debated; “Ezrahite” points to descent from Zerah, or possibly to a native-born man (ezrach)."}),
ot2_jeduthun:OT2({name:"Jeduthun",forms:["Jeduthun"],resp:"jeh-DOO-thun",say:"jeh doo thun",heb:"יְדוּתוּן",tr:"Yedutun",strong:"H3038",books:["1chr","2chr","ps"],
 plain:"A Levite of Merari’s family, one of David’s three chief musicians with Asaph and Heman, whose sons “prophesied with a harp, to give thanks and to praise the LORD” (25:3). The name is often linked to the verb yadah, “to give thanks” or “praise,” but the meaning is not certain. Psalms 39, 62 and 77 are headed “to Jeduthun,” which may name him, his choir, or a tune.",
 bg:"In Chronicles his sons were also gatekeepers (16:42)."}),
// ================= Chronicles: David to the exile =================
ot2_david:OT2({name:"David",forms:["David"],resp:"DAY-vid",say:"day vid",heb:"דָּוִד",tr:"David",strong:"H1732",books:["1chr","2chr","ps","prov","eccl","song"],
 plain:"Israel’s second king, the shepherd boy who became ruler of all Israel, captured Jerusalem (1 Chronicles 11:4–7), planned the temple, and gave the Psalms much of their voice. The meaning of his name is not certain: it is usually taken as “beloved,” from the root of dod, “beloved one” or “uncle.”",
 bg:"Chronicles remembers David above all as the king who organized Israel’s worship and promised that his house would last (1 Chronicles 17:11–14). Jesus calls himself “the Root and the offspring of David” (Revelation 22:16)."}),
ot2_solomon:OT2({name:"Solomon",forms:["Solomon"],resp:"SOL-uh-mun",say:"sol uh mun",heb:"שְׁלֹמֹה",tr:"Shelomoh",strong:"H8010",books:["1chr","2chr","ps","prov","song"],
 plain:"David’s son and successor, who built the temple and was famed for wisdom, wealth and a peaceful reign. His Hebrew name, Shelomoh, is built on shalom, “peace”; God told David, “his name shall be Solomon, and I will give peace and quietness unto Israel in his days” (1 Chronicles 22:9).",
 bg:"His other name, Jedidiah, means “beloved of the LORD” (2 Samuel 12:25). Proverbs, Ecclesiastes and the Song of Solomon each open by linking themselves to him (Proverbs 1:1; Ecclesiastes 1:1; Song of Solomon 1:1), though readers differ on how far that means authorship."}),
ot2_hiram:OT2({name:"Hiram / Huram",forms:["Hiram","Huram"],resp:"HYE-rum / HYOO-rum",say:"hye rum, hyoo rum",heb:"חִירָם / חוּרָם",tr:"Chiram / Churam",strong:"",books:["1chr","2chr"],
 plain:"The king of Tyre, a Phoenician city, who sent David cedar and builders for his palace (1 Chronicles 14:1) and later supplied Solomon with cedar, workmen and sailors for the temple (2 Chronicles 2:3–16). Chronicles often spells the name Huram; the book of Kings spells it Hiram. The name is usually taken as short for Ahiram, “my brother is exalted.”",
 bg:"He answered Solomon, “Blessed be the LORD God of Israel, that made heaven and earth” (2 Chronicles 2:12)."}),
ot2_huram_abi:OT2({name:"Huram-abi (the craftsman)",forms:[],resp:"HYOO-rum-AY-bye",say:"hyoo rum ay bye",heb:"חוּרָם אָבִי",tr:"Churam ʾAvi",strong:"",books:["2chr"],
 plain:"A skilled worker in bronze, gold, cloth and carving sent by the king of Tyre to Solomon; his mother was of the tribe of Dan and his father a man of Tyre (2:13–14). He made the pillars, pots and vessels for the temple (4:11–16). The KJV’s “Huram my father’s” (2:13) probably renders his name Huram-abi, where abi, “my father,” may be an honorific for a master craftsman.",
 bg:"The book of Kings calls him Hiram (1 Kings 7:13–14)."}),
ot2_obededom:OT2({name:"Obed-edom",forms:["Obed-edom"],resp:"OH-bed-EE-dum",say:"oh bed ee dum",heb:"עֹבֵד אֱדֹם",tr:"ʿOved ʾEdom",strong:"H5654",books:["1chr","2chr"],
 plain:"The man in whose house the ark stayed three months, so that “the LORD blessed the house of Obed-edom, and all that he had” (13:14). A Levite of this name was a singer and gatekeeper under David (15:18, 21, 24; 16:5, 38; 26:4–8), and scholars debate whether this is one man or more. The name means “servant of Edom”; Edom here may be the nation, a person, or even a divine name.",
 bg:"His family still had charge of the temple’s vessels generations later (2 Chronicles 25:24)."}),
ot2_uzza:OT2({name:"Uzza",forms:["Uzza"],resp:"UZ-uh",say:"uz uh",heb:"עֻזָּא",tr:"ʿUzza",strong:"H5798",books:["1chr"],
 plain:"One of the two drivers of the cart that carried the ark, who “put forth his hand to hold the ark” and was struck dead (13:7–10). The name apparently comes from oz, “strength.”",
 bg:"The ark was meant to be carried on the shoulders of the Levites (15:2, 15), not on a cart (13:7)."}),
ot2_perezuzza:OT2({name:"Perez-uzza",forms:["Perez-uzza"],resp:"PEE-rez-UZ-uh",say:"pee rez uz uh",heb:"פֶּרֶץ עֻזָּא",tr:"Peretz ʿUzza",strong:"",books:["1chr"],
 plain:"The place where Uzza died, named after “the LORD had made a breach upon Uzza: wherefore that place is called Perez-uzza to this day” (13:11). The name means “breach of Uzza.”",
 bg:"David was “displeased” and “afraid of God that day,” and left the ark at the house of Obed-edom (13:11–14)."}),
ot2_ornan:OT2({name:"Ornan (Araunah)",forms:["Ornan"],resp:"OR-nan",say:"or nan",heb:"אָרְנָן",tr:"ʾOrnan",strong:"H771",books:["1chr","2chr"],
 plain:"The Jebusite who owned the threshing floor where the destroying angel stopped, where David built an altar (21:15–26) and where Solomon later built the temple (2 Chronicles 3:1). Second Samuel calls him Araunah. The meaning of the name is uncertain; some think it is a non-Hebrew title meaning “lord.”",
 bg:"David refused it as a gift: “I will not take that which is thine for the LORD, nor offer burnt offerings without cost” (21:24)."}),
ot2_moriah:OT2({name:"Moriah",forms:["Moriah"],resp:"mo-RYE-uh",say:"mo rye uh",heb:"מוֹרִיָּה",tr:"Moriyah",strong:"H4179",books:["2chr"],
 plain:"The mount in Jerusalem where Solomon began to build the temple, “where the LORD appeared unto David his father” (3:1). It is the same name as the land where Abraham was told to offer Isaac (Genesis 22:2). The meaning is uncertain; it is often linked to the verb raah, “to see,” echoing Abraham’s words “in the mount of the LORD it shall be seen” (Genesis 22:14).",
 bg:"Latter-day Saint scripture calls Abraham’s offering of Isaac “a similitude of God and his Only Begotten Son” (Jacob 4:5)."}),
ot2_rehoboam:OT2({name:"Rehoboam",forms:["Rehoboam"],resp:"ree-huh-BOH-um",say:"ree huh bo um",heb:"רְחַבְעָם",tr:"Rechavʿam",strong:"H7346",books:["1chr","2chr"],
 plain:"Solomon’s son, who lost ten tribes when he answered the people harshly instead of lightening their load (10:1–19); only Judah and Benjamin stayed with him (11:1–4). His name means “he enlarges the people” or “the people are enlarged,” a name that reads ironically for a king whose kingdom shrank.",
 bg:"Once established, he “forsook the law of the LORD, and all Israel with him,” and Shishak of Egypt invaded (12:1–2)."}),
ot2_abijah:OT2({name:"Abijah (king of Judah)",forms:["Abijah"],resp:"uh-BYE-juh",say:"uh bye juh",heb:"אֲבִיָּה",tr:"ʾAviyyah",strong:"H29",books:["1chr","2chr"],
 plain:"Rehoboam’s son and successor, who from Mount Zemaraim told Jeroboam’s army that God was with Judah, and won a great victory (13:4–20). The name means “my father is the LORD,” using Yah.",
 bg:"The book of Kings calls him Abijam and judges him harshly (1 Kings 15:1–3), while Chronicles stresses his speech and his victory."}),
ot2_abijah_priest:OT2({name:"Abijah (priestly division)",forms:[],resp:"uh-BYE-juh",say:"uh bye juh",heb:"אֲבִיָּה",tr:"ʾAviyyah",strong:"H29",books:["1chr"],
 plain:"The head of the family given the eighth of the twenty-four divisions of priests that David organized (24:10). The name means “my father is the LORD.”",
 bg:"Zacharias, father of John the Baptist, served “in the course of Abia” (Luke 1:5)."}),
ot2_asa:OT2({name:"Asa",forms:["Asa"],resp:"AY-suh",say:"ay suh",heb:"אָסָא",tr:"ʾAsa",strong:"H609",books:["1chr","2chr"],
 plain:"A king of Judah who removed idols and trusted the LORD against a huge Ethiopian army (14:1–15), but later relied on Syria’s king, and when diseased “sought not to the LORD, but to the physicians” (16:12). The meaning of the name is uncertain; it is often explained as “healer” or “physician,” which would sharpen the irony of 16:12.",
 bg:"The prophet Azariah told him, “The LORD is with you, while ye be with him” (15:2)."}),
ot2_jehoshaphat:OT2({name:"Jehoshaphat",forms:["Jehoshaphat"],resp:"jeh-HOSH-uh-fat",say:"jeh hosh uh fat",heb:"יְהוֹשָׁפָט",tr:"Yehoshafat",strong:"H3092",books:["1chr","2chr"],
 plain:"Asa’s son, a king of Judah who sent teachers through the cities (17:7–9), appointed judges (19:5–7), and met a huge enemy coalition by praying and sending singers ahead of the army (20:1–22). His name means “the LORD has judged” or “the LORD judges.”",
 bg:"The name fits his charge to the judges: “Take heed what ye do: for ye judge not for man, but for the LORD” (19:6). The “valley of Jehoshaphat” in Joel 3:2 uses the same name."}),
ot2_joash:OT2({name:"Joash (king of Judah)",forms:["Joash"],resp:"JOH-ash",say:"joh ash",heb:"יוֹאָשׁ",tr:"Yoʾash",strong:"H3101",books:["1chr","2chr"],
 plain:"The boy king of Judah, rescued as a baby from Athaliah’s killing of the royal family, hidden in the temple six years, and crowned at seven (22:11–23:11; 24:1). The name, also spelled Jehoash, is usually explained as “the LORD has given,” though the meaning is not certain.",
 bg:"He did right “all the days of Jehoiada the priest” (24:2), then turned to idols and had Jehoiada’s son Zechariah stoned in the temple court (24:17–22); many take this as the Zechariah Jesus names in Matthew 23:35."}),
ot2_joash_israel:OT2({name:"Joash (king of Israel)",forms:[],resp:"JOH-ash",say:"joh ash",heb:"יוֹאָשׁ",tr:"Yoʾash",strong:"H3101",books:["2chr"],
 plain:"The king of the northern kingdom, son of Jehoahaz, who defeated Amaziah of Judah at Beth-shemesh and broke down part of Jerusalem’s wall (25:17–24). The name, also spelled Jehoash, is usually explained as “the LORD has given.”",
 bg:"Second Kings tells the same story (2 Kings 14:8–14)."}),
ot2_uzziah:OT2({name:"Uzziah",forms:["Uzziah"],resp:"uh-ZYE-uh",say:"uh zye uh",heb:"עֻזִּיָּהוּ",tr:"ʿUzziyyahu",strong:"H5818",books:["1chr","2chr"],
 plain:"A king of Judah for fifty-two years (26:3), who prospered “as long as he sought the LORD” (26:5), built up the army and defenses (26:6–15), then grew proud, tried to burn incense in the temple, and was struck with leprosy (26:16–21). His name means “my strength is the LORD” or “the LORD is my strength.”",
 bg:"The book of Kings usually calls him Azariah (2 Kings 15:1–2). Isaiah saw his vision of the LORD “in the year that king Uzziah died” (Isaiah 6:1)."}),
ot2_ahaz:OT2({name:"Ahaz",forms:["Ahaz"],resp:"AY-haz",say:"ay haz",heb:"אָחָז",tr:"ʾAchaz",strong:"H271",books:["1chr","2chr"],
 plain:"A king of Judah who made idols, sacrificed to other gods, and shut the temple doors (28:1–4, 24). The name means “he has grasped,” and is probably short for Jehoahaz, “the LORD has grasped.”",
 bg:"Isaiah gave Ahaz the sign of Immanuel (Isaiah 7:10–14), which the Book of Mormon quotes (2 Nephi 17:10–14)."}),
ot2_hezekiah:OT2({name:"Hezekiah",forms:["Hezekiah"],resp:"hez-ih-KYE-uh",say:"hez ih kye uh",heb:"חִזְקִיָּהוּ",tr:"Chizqiyyahu",strong:"H2396",books:["1chr","2chr","prov"],
 plain:"A king of Judah who reopened and cleansed the temple (29:3–19), held a great Passover (30:1–27), and trusted God when Assyria threatened Jerusalem (32:7–22). His name means “the LORD strengthens” or “my strength is the LORD.”",
 bg:"He had a tunnel dug to bring the Gihon spring inside the city walls (2 Chronicles 32:30). “The men of Hezekiah king of Judah” also copied out more of Solomon’s proverbs (Proverbs 25:1)."}),
ot2_manasseh_king:OT2({name:"Manasseh (king of Judah)",forms:[],resp:"muh-NASS-uh",say:"muh nass uh",heb:"מְנַשֶּׁה",tr:"Menashsheh",strong:"H4519",books:["1chr","2chr"],
 plain:"Hezekiah’s son and the longest-reigning king of Judah, fifty-five years (33:1). He rebuilt the idol altars, put them in the temple courts, and led the people to do “worse than the heathen” (33:2–9); carried captive to Babylon, “he humbled himself greatly before the God of his fathers,” and God brought him back (33:11–13). The name means “making to forget” (Genesis 41:51), the same name as Joseph’s son and his tribe.",
 bg:"The book of Kings blames his sins for Judah’s fall (2 Kings 21:10–15; 24:3), while Chronicles adds his repentance."}),
ot2_josiah:OT2({name:"Josiah",forms:["Josiah"],resp:"joh-SYE-uh",say:"joh sye uh",heb:"יֹאשִׁיָּהוּ",tr:"Yoʾshiyyahu",strong:"H2977",books:["1chr","2chr"],
 plain:"A king of Judah who became king at eight, began to seek God at sixteen, and at twenty cleansed the land of idols (34:1–3). When the book of the law was found in the temple he tore his clothes and led the people in renewing the covenant (34:14–32), then kept a great Passover (35:1–19). The meaning of his name is uncertain; “the LORD supports” and “the LORD heals” have both been suggested.",
 bg:"He was killed at Megiddo, and Jeremiah lamented for him (35:20–25). Lehi’s call came in the first year of the reign of Josiah’s son Zedekiah (1 Nephi 1:4)."}),
ot2_zedekiah:OT2({name:"Zedekiah",forms:["Zedekiah"],resp:"zed-ih-KYE-uh",say:"zed ih kye uh",heb:"צִדְקִיָּהוּ",tr:"Tsidqiyyahu",strong:"H6667",books:["1chr","2chr"],
 plain:"The last king of Judah, who reigned eleven years and “humbled not himself before Jeremiah the prophet” (36:11–12); Babylon burned the temple and Jerusalem at the end of his reign (36:17–19). His birth name was Mattaniah, and Nebuchadnezzar renamed him Zedekiah (2 Kings 24:17), a name meaning “the LORD is my righteousness” or “righteousness of the LORD.”",
 bg:"Lehi’s ministry began in his first year (1 Nephi 1:4), and the people of Zarahemla left Jerusalem when he was carried captive to Babylon (Omni 1:15)."}),
ot2_zedekiah_chenaanah:OT2({name:"Zedekiah (son of Chenaanah)",forms:[],resp:"zed-ih-KYE-uh",say:"zed ih kye uh",heb:"צִדְקִיָּהוּ",tr:"Tsidqiyyahu",strong:"H6667",books:["2chr"],
 plain:"The false prophet who made horns of iron and told Ahab, “With these thou shalt push Syria until they be consumed” (18:10), then struck the true prophet Micaiah on the cheek (18:23). He shares the name “the LORD is my righteousness” with Judah’s last king.",
 bg:"Micaiah told Ahab that a lying spirit was in the mouth of all these prophets (18:21–22), and Ahab was killed in the battle (18:33–34)."}),
ot2_cyrus:OT2({name:"Cyrus",forms:["Cyrus"],resp:"SYE-rus",say:"sye rus",heb:"כּוֹרֶשׁ",tr:"Koresh",strong:"H3566",books:["2chr"],
 plain:"The king of Persia who conquered Babylon in 539 BC and issued the decree that let the Jews return to Jerusalem and rebuild the temple (36:22–23), the closing words of the Hebrew Bible. The Hebrew form of his name is Koresh; its origin and meaning are uncertain.",
 bg:"Isaiah named him more than a century earlier as the LORD’s “shepherd” and “anointed” (Isaiah 44:28; 45:1). Ezra 1:1–3 repeats the decree."}),
ot2_levites:OT2({name:"Levites",forms:["Levites"],resp:"LEE-vites",say:"lee vites",heb:"לְוִיִּם",tr:"Leviyyim",strong:"H3881",books:["1chr","2chr"],
 plain:"The tribe of Levi, set apart to serve at the tabernacle and then the temple. In Chronicles they are the singers, gatekeepers, treasurers, teachers and helpers, while the priests of Aaron’s line serve at the altar (1 Chronicles 23:3–5, 28–32). Levi means “joined” or “attached” (Genesis 29:34).",
 bg:"Hezekiah’s day: the Levites “were more upright in heart to sanctify themselves than the priests” (2 Chronicles 29:34)."}),
ot2_israel:OT2({name:"Israel",forms:["Israel"],resp:"IZ-ray-el",say:"izz ray ell",heb:"יִשְׂרָאֵל",tr:"Yisraʾel",strong:"H3478",books:["1chr","2chr","ps","prov","eccl","song","lam"],
 plain:"The name God gave Jacob after he wrestled at Peniel, and then the name of his descendants and nation. Genesis explains it as “as a prince hast thou power with God and with men, and hast prevailed” (32:28); scholars debate whether it means “he strives with God” or “God strives.” In Chronicles it can mean the whole people or, after the kingdom splits (2 Chronicles 10), the northern kingdom as opposed to Judah.",
 bg:"The Psalms often pair it with Jacob: “Jacob shall rejoice, and Israel shall be glad” (Psalm 14:7)."}),
ot2_jacob:OT2({name:"Jacob",forms:["Jacob"],resp:"JAY-kub",say:"jay cub",heb:"יַעֲקֹב",tr:"Yaʿaqov",strong:"H3290",books:["1chr","ps","lam"],
 plain:"Isaac’s younger twin and the father of the twelve tribes. The name means “heel-holder,” so “he supplants” or “he cheats”: he was born holding Esau’s heel (Genesis 25:26), and Esau said, “he hath supplanted me these two times” (Genesis 27:36). In Psalms and Lamentations “Jacob” is also a poetic name for the whole people.",
 bg:"God renamed him Israel (Genesis 32:28), and the two names are often paired in poetry, as in “The God of Jacob is our refuge” (Psalm 46:7)."}),
ot2_judah:OT2({name:"Judah",forms:["Judah"],resp:"JOO-duh",say:"joo duh",heb:"יְהוּדָה",tr:"Yehudah",strong:"H3063",books:["1chr","2chr","ps","prov","lam"],
 plain:"Jacob’s fourth son by Leah, his tribe, and later the southern kingdom ruled by David’s family after the kingdom split. The name means “praise”: Leah said, “Now will I praise the LORD: therefore she called his name Judah” (Genesis 29:35). The words “Jew” and “Jewish” come from it.",
 bg:"The LORD “hath chosen Judah to be the ruler” (1 Chronicles 28:4), and Jesus came from this tribe (Matthew 1:2–3)."}),
ot2_korah:OT2({name:"Korah",forms:["Korah"],resp:"KOR-uh",say:"kor uh",heb:"קֹרַח",tr:"Qorach",strong:"H7141",books:["1chr","ps"],
 plain:"The Levite who rebelled against Moses and Aaron (Numbers 16). His family did not die out (Numbers 26:11); in Chronicles his descendants are gatekeepers of the tabernacle (9:19), and eleven psalms are headed “for the sons of Korah” (42; 44–49; 84–85; 87–88). The name is usually understood to mean “bald.”",
 bg:"Their psalms include Psalm 42, “As the hart panteth after the water brooks,” and Psalm 84, “How amiable are thy tabernacles, O LORD of hosts!”"}),
ot2_namesake:OT2({name:"Another man of this name",forms:[],resp:"",say:"",heb:"",tr:"",strong:"",books:["1chr","2chr"],
 plain:"A different man with the same name as a better-known person in Chronicles. He appears only in a genealogy or list, and the book says little more about him. The name has the same meaning as on the card for the better-known man.",
 bg:""}),
// ================= Job =================
ot2_job:OT2({name:"Job",forms:["Job"],resp:"JOHB",say:"johb",heb:"אִיּוֹב",tr:"ʾIyyov",strong:"H347",books:["job"],
 plain:"The righteous man of the land of Uz who lost his children, wealth and health, and argued with his friends about why (1:1–2:10; chapters 3–37) until God answered him out of the whirlwind (38:1). The meaning of his name is uncertain: it may come from the word for “enemy” (oyev), so “the one treated as an enemy” (compare “holdest me for thine enemy,” 13:24), or from a word meaning “repentant.”",
 bg:"Ezekiel names Job with Noah and Daniel as a righteous man (Ezekiel 14:14), and James cites “the patience of Job” (James 5:11). The Lord told Joseph Smith in Liberty Jail, “Thou art not yet as Job” (D&C 121:10)."}),
ot2_uz:OT2({name:"Uz",forms:["Uz"],resp:"UZ",say:"uzz",heb:"עוּץ",tr:"ʿUts",strong:"H5780",books:["job","lam"],
 plain:"The land where Job lived (1:1). Its location is uncertain, but the clues point to the area east or southeast of Israel near Edom, and Lamentations 4:21 speaks of Edom as dwelling “in the land of Uz.” The meaning of the name is unknown.",
 bg:"Uz is also a man’s name elsewhere in the Bible (Genesis 10:23; 36:28)."}),
ot2_eliphaz:OT2({name:"Eliphaz",forms:["Eliphaz"],resp:"EL-ih-faz",say:"ell ih faz",heb:"אֱלִיפַז",tr:"ʾElifaz",strong:"H464",books:["job"],
 plain:"The first of Job’s three friends to speak, “the Temanite” (2:11; chapters 4–5, 15, 22), who holds that suffering falls on the guilty. His name is often explained as “my God is fine gold” (El + paz), but this is uncertain. Teman was a district of Edom famed for its wise men (Jeremiah 49:7).",
 bg:"He describes a night vision in which “a spirit passed before my face” (4:15), and at the end the LORD tells him he has not spoken of God “the thing that is right, as my servant Job hath” (42:7)."}),
ot2_bildad:OT2({name:"Bildad",forms:["Bildad"],resp:"BIL-dad",say:"bill dad",heb:"בִּלְדַּד",tr:"Bildad",strong:"H1085",books:["job"],
 plain:"The second of Job’s friends, “the Shuhite” (2:11), who defends God’s justice by appealing to ancestral tradition (chapters 8, 18, 25). The meaning of the name is unknown; some guess “Bel has loved,” but that is only a guess.",
 bg:"He tells Job to “inquire … of the former age, and prepare thyself to the search of their fathers” (8:8)."}),
ot2_zophar:OT2({name:"Zophar",forms:["Zophar"],resp:"ZOH-far",say:"zoh far",heb:"צוֹפַר",tr:"Tsofar",strong:"H6691",books:["job"],
 plain:"The third of Job’s friends, “the Naamathite” (2:11), who speaks bluntly: “God exacteth of thee less than thine iniquity deserveth” (11:6; chapters 11, 20). The meaning of the name is unknown; some link it to a word for a small bird.",
 bg:"The LORD rebuked all three friends, and they were spared only when Job prayed for them (42:7–10)."}),
ot2_elihu:OT2({name:"Elihu",forms:["Elihu"],resp:"ee-LYE-hyoo",say:"ee lye hyoo",heb:"אֱלִיהוּא",tr:"ʾElihu",strong:"H453",books:["job"],
 plain:"The younger man, “the son of Barachel the Buzite,” who waited until the older men finished and then spoke, angry that Job justified himself rather than God (32:2–6). His name means “he is my God” (El + hu), a name that fits a speaker whose whole argument is God’s greatness (chapters 32–37).",
 bg:"Unlike the three friends, Elihu is not rebuked at the end; the LORD answers from the whirlwind right after his speech (37:23–38:1)."}),
ot2_behemoth:OT2({name:"Behemoth",forms:["Behemoth"],resp:"buh-HEE-muth",say:"buh hee muth",heb:"בְּהֵמוֹת",tr:"Behemot",strong:"H930",books:["job"],
 plain:"A huge, powerful animal that God points out to Job: “he eateth grass as an ox,” “his bones are as strong pieces of brass,” “he is the chief of the ways of God” (40:15–19). Behemoth is the plural of behemah, “beast,” so the name means something like “the great beast”; scholars debate whether it is the hippopotamus, another real animal, or a mythic creature.",
 bg:"God says, “which I made with thee” (40:15), reminding Job that this creature is a fellow creature."}),
ot2_leviathan:OT2({name:"Leviathan",forms:["Leviathan"],resp:"luh-VYE-uh-thun",say:"luh vye uh thun",heb:"לִוְיָתָן",tr:"Livyatan",strong:"H3882",books:["job","ps"],
 plain:"A fearsome sea creature that cannot be caught or tamed (Job 41), which no one is “so fierce that dare stir him up” (Job 41:10). The name is usually linked to a root meaning “to twist” or “coil,” so “the coiling one.” In Psalm 74:14 God “brakest the heads of leviathan in pieces,” and Psalm 104:26 pictures it playing in the sea.",
 bg:"Isaiah 27:1 says the LORD will punish “leviathan the piercing serpent.” Whether it is the crocodile or a sea monster of chaos is debated."}),
ot2_jemima:OT2({name:"Jemima, Kezia and Keren-happuch",forms:["Jemima","Kezia","Keren-happuch"],resp:"juh-MYE-muh / kuh-ZYE-uh / KAIR-un-HAP-uk",say:"juh mye muh, kuh zye uh, kair un hap uck",heb:"יְמִימָה / קְצִיעָה / קֶרֶן הַפּוּךְ",tr:"Yemimah / Qetsiʿah / Qeren-happukh",strong:"H3224 / H7103 / H7163",books:["job"],
 plain:"The names of Job’s three new daughters (42:14), each about beauty. Jemima probably means “dove” (the meaning is uncertain), Kezia is “cassia,” a fragrant spice, and Keren-happuch means “horn of eye paint,” the little horn used to hold dark cosmetic.",
 bg:"“In all the land were no women found so fair as the daughters of Job: and their father gave them inheritance among their brethren” (42:15)."}),
ot2_satan:OT2({name:"Satan",forms:["Satan"],resp:"SAY-tun",say:"say tun",heb:"שָׂטָן",tr:"satan",strong:"H7854",books:["job","1chr","ps"],
 plain:"The Hebrew word satan means “adversary,” “opponent” or “accuser.” In Job 1–2 it has the article, “the satan,” and is the one who comes among the sons of God and challenges Job’s integrity (1:6–12; 2:1–7). In 1 Chronicles 21:1 an adversary “stood up against Israel, and provoked David to number Israel,” and in Psalm 109:6 the word may simply mean a human accuser.",
 bg:"The Pearl of Great Price names Satan as the one who “rebelled against me, and sought to destroy the agency of man” (Moses 4:3)."}),
// ================= Psalms: titles and musical words =================
ot2_selah:OT2({name:"Selah",forms:["Selah"],resp:"SEE-luh",say:"see luh",heb:"סֶלָה",tr:"Selah",strong:"H5542",books:["ps"],
 plain:"A word that stands 71 times in the Psalms (and three times in Habakkuk 3), usually at the end of a verse or stanza. Its meaning is unknown. Guesses include a pause, a musical interlude, a “lifting up” of voices or instruments, or “forever.”",
 bg:"The Greek Septuagint renders it diapsalma, probably “an instrumental interlude,” but that was also a guess."}),
ot2_maschil:OT2({name:"Maschil",forms:["Maschil"],resp:"MASS-kil",say:"mass kill",heb:"מַשְׂכִּיל",tr:"Maskil",strong:"H4905",books:["ps"],
 plain:"A label in thirteen psalm headings (32, 42, 44, 45, 52–55, 74, 78, 88, 89, 142). It is usually taken to mean a “psalm of instruction” or a “skillful” psalm, from the verb sakal, “to have insight.” The exact sense is uncertain.",
 bg:"The same verb is used in Psalm 32:8, “I will instruct thee and teach thee in the way which thou shalt go.”"}),
ot2_michtam:OT2({name:"Michtam",forms:["Michtam"],resp:"MIK-tam",say:"mick tam",heb:"מִכְתָּם",tr:"Miktam",strong:"H4387",books:["ps"],
 plain:"A label in six psalm headings (16 and 56–60). Its meaning is unknown. Some link it to ketem, “gold,” so a “golden” or precious psalm; others to a word meaning “to write” or “to cover.”",
 bg:"Peter quotes Psalm 16 as David speaking of the resurrection of Christ (Acts 2:25–31)."}),
ot2_shiggaion:OT2({name:"Shiggaion",forms:["Shiggaion"],resp:"shig-GAY-on",say:"shig gay on",heb:"שִׁגָּיוֹן",tr:"Shiggayon",strong:"H7692",books:["ps"],
 plain:"A label in the heading of Psalm 7 alone (Habakkuk 3:1 has a related plural, Shigionoth). Its meaning is uncertain; it may come from a verb meaning “to wander” or “reel,” suggesting an excited, irregular song, but this is a guess.",
 bg:"The heading adds that David sang it “concerning the words of Cush the Benjamite.”"}),
ot2_neginoth:OT2({name:"Neginoth",forms:["Neginoth"],resp:"NEG-ih-noth",say:"neg ih noth",heb:"נְגִינוֹת",tr:"Neginot",strong:"H5058",books:["ps"],
 plain:"A word in the headings of six psalms (4, 6, 54, 55, 67, 76): “to the chief Musician on Neginoth.” It means “stringed instruments,” from nagan, “to play a stringed instrument,” so these psalms were to be sung with harps or lyres.",
 bg:"Habakkuk 3:19 ends with the same word: “To the chief singer on my stringed instruments.”"}),
ot2_gittith:OT2({name:"Gittith",forms:["Gittith"],resp:"GIT-ith",say:"git ith",heb:"גִּתִּית",tr:"Gittit",strong:"H1665",books:["ps"],
 plain:"A word in the headings of Psalms 8, 81 and 84. Its meaning is uncertain: it probably means “of Gath,” the Philistine city, naming an instrument or a tune from there, or it may relate to gath, “winepress,” suggesting a vintage song.",
 bg:"Obed-edom the Gittite, a man of Gath, kept the ark and later served as a Levite musician (1 Chronicles 13:13; 15:18)."}),
ot2_sheminith:OT2({name:"Sheminith",forms:["Sheminith"],resp:"SHEM-ih-nith",say:"shem ih nith",heb:"שְׁמִינִית",tr:"Sheminit",strong:"H8067",books:["1chr","ps"],
 plain:"A musical word meaning “the eighth,” found in the headings of Psalms 6 and 12 and in 1 Chronicles 15:21, where harps are played “on Sheminith to excel.” It may refer to an eight-stringed instrument, an octave, or a low pitch or melody, but nobody knows for sure.",
 bg:"In 1 Chronicles 15:20–21 it is paired with Alamoth, probably a contrast between higher and lower voices or instruments."}),
ot2_alamoth:OT2({name:"Alamoth",forms:["Alamoth"],resp:"AL-uh-moth",say:"al uh moth",heb:"עֲלָמוֹת",tr:"ʿAlamot",strong:"H5961",books:["1chr","ps"],
 plain:"A musical word in the heading of Psalm 46 and in 1 Chronicles 15:20, where psalteries are played “on Alamoth.” It is the plural of almah, “young woman,” so it probably means a high, “maidens’” pitch, whether women’s voices or a soprano range.",
 bg:"The singular, almah, is the word translated “virgin” in the KJV of Isaiah 7:14."}),
ot2_aijeleth:OT2({name:"Aijeleth Shahar",forms:["Aijeleth Shahar"],resp:"EYE-uh-leth SHAY-har",say:"eye uh leth shay har",heb:"אַיֶּלֶת הַשַּׁחַר",tr:"ʾAyyelet ha-Shachar",strong:"",books:["ps"],
 plain:"In the heading of Psalm 22: “to the chief Musician upon Aijeleth Shahar.” The Hebrew words mean “the hind (doe) of the dawn.” It probably names the tune the psalm was sung to, though it may be a poetic title for the psalm itself.",
 bg:"Psalm 22 opens with the words Jesus cried from the cross, “My God, my God, why hast thou forsaken me?” (Matthew 27:46)."}),
ot2_muthlabben:OT2({name:"Muth-labben",forms:["Muth-labben"],resp:"MOOTH-LAB-ben",say:"mooth lab ben",heb:"עַל־מוּת לַבֵּן",tr:"ʿal-mut labben",strong:"",books:["ps"],
 plain:"In the heading of Psalm 9: “upon Muth-labben.” The Hebrew words mean “death of the son,” but nobody knows what is meant. It may be the name of a tune, or the words may have been altered, since ancient translators read them differently.",
 bg:""}),
ot2_shoshannim:OT2({name:"Shoshannim",forms:["Shoshannim"],resp:"sho-SHAN-im",say:"sho shan im",heb:"שׁוֹשַׁנִּים",tr:"Shoshannim",strong:"H7799",books:["ps"],
 plain:"In the headings of Psalms 45, 69 and 80 (Psalm 80 reads “Shoshannim-Eduth,” “lilies, a testimony”). The word means “lilies,” and probably names the tune the psalm was sung to, or perhaps a lily-shaped instrument.",
 bg:"The same word is the “lily” of Song of Solomon 2:1–2."}),
ot2_higgaion:OT2({name:"Higgaion",forms:["Higgaion"],resp:"hig-GAY-on",say:"hig gay on",heb:"הִגָּיוֹן",tr:"Higgayon",strong:"H1902",books:["ps"],
 plain:"A word in Psalm 9:16, “Higgaion. Selah.” It comes from a verb meaning to murmur or meditate, so it may mean “meditation” or a soft musical sound. Psalm 92:3 uses the same word for the “solemn sound” of the harp.",
 bg:"Psalm 19:14 also uses it: “the meditation of my heart.”"}),
ot2_praiseye:OT2({name:"Hallelujah (Praise ye the LORD)",forms:["Praise ye the LORD"],resp:"hal-uh-LOO-yuh",say:"hal uh loo yuh",heb:"הַלְלוּ־יָהּ",tr:"Halleluyah",strong:"H1984 / H3050",books:["ps"],
 plain:"In the KJV this is the call “Praise ye the LORD.” In Hebrew it is a single phrase, hallelu-yah: hallelu is a command to a group, “praise!”, and yah is a short form of the LORD’s name. The KJV translates it instead of transliterating it, so English readers do not see the word “hallelujah.”",
 bg:"Psalms 113–118 are the Hallel, sung at Passover, and the hymn at the Last Supper was probably part of it (Matthew 26:30). The word stays in Greek form in the KJV of Revelation 19:1, “Alleluia.”"}),
ot2_jehovah:OT2({name:"Jehovah (the LORD)",forms:["Jehovah"],resp:"juh-HOH-vuh",say:"juh hoh vuh",heb:"יהוה",tr:"YHWH",strong:"H3068",books:["ps"],
 plain:"God’s personal name, written in Hebrew with the four letters YHWH and probably pronounced Yahweh. Wherever the Hebrew has this name, the KJV prints LORD in small capitals; it spells out “JEHOVAH” in only a few places, such as Psalm 83:18, “whose name alone is JEHOVAH.” “Jehovah” blends YHWH with the vowels of Adonai, “my Lord,” which readers said aloud instead of the name.",
 bg:"Latter-day Saints understand Jehovah to be the premortal Jesus Christ (D&C 110:3–4)."}),
ot2_jah:OT2({name:"Jah (Yah)",forms:["Jah"],resp:"YAH",say:"yah",heb:"יָהּ",tr:"Yah",strong:"H3050",books:["ps"],
 plain:"A short form of God’s name YHWH, used in poetry. In Psalm 68:4 the KJV reads “extol him that rideth upon the heavens by his name JAH.” The same short name ends “hallelujah” (“praise Yah”) and many Hebrew names, such as Elijah, “my God is Yah.”",
 bg:"Moses’ song at the Red Sea already used it: “The LORD is my strength and song” (Exodus 15:2)."}),
ot2_zion:OT2({name:"Zion",forms:["Zion"],resp:"ZYE-on",say:"zye on",heb:"צִיּוֹן",tr:"Tsiyyon",strong:"H6726",books:["1chr","2chr","ps","song","lam"],
 plain:"The fortified hill in Jerusalem that David took from the Jebusites: “David took the castle of Zion, which is the city of David” (1 Chronicles 11:5). The name then came to mean the temple mount, Jerusalem and God’s people. The meaning is unknown; “citadel” or “fortress” is the most common suggestion. In Lamentations, Zion is a grieving woman, “the daughter of Zion” (Lamentations 1:6; 2:1).",
 bg:"“The LORD hath chosen Zion; he hath desired it for his habitation” (Psalm 132:13). Latter-day Saint scripture says the Lord called his people Zion “because they were of one heart and one mind” (Moses 7:18)."}),
ot2_sion:OT2({name:"Sion",forms:["Sion"],resp:"SYE-on",say:"sye on",heb:"צִיּוֹן",tr:"Tsiyyon",strong:"H6726",books:["ps"],
 plain:"The KJV’s spelling of Zion in Psalm 65:1, “Praise waiteth for thee, O God, in Sion.” Sion is the Greek and Latin form of the same Hebrew name, meaning the temple hill in Jerusalem or the city itself.",
 bg:"The New Testament also uses “Sion” (Romans 9:33; Hebrews 12:22)."}),
ot2_rahab:OT2({name:"Rahab (poetic name)",forms:["Rahab"],resp:"RAY-hab",say:"ray hab",heb:"רַהַב",tr:"Rahav",strong:"H7294",books:["ps"],
 plain:"A poetic name for Egypt in Psalm 87:4 (“Rahab and Babylon”) and a sea monster of chaos that God crushes in Psalm 89:10 (“thou hast broken Rahab in pieces”). The word means “arrogant” or “proud one.” It is a different word from Rahab of Jericho (Joshua 2), whose name is spelled differently in Hebrew.",
 bg:"Isaiah 51:9 recalls the same images: “Art thou not it that hath cut Rahab, and wounded the dragon?” Psalm 87 pictures even Egypt and Babylon counted among those “born” in Zion (87:4–6)."}),
ot2_hermon:OT2({name:"Hermon",forms:["Hermon"],resp:"HER-mun",say:"her mun",heb:"חֶרְמוֹן",tr:"Chermon",strong:"H2768",books:["1chr","ps","song"],
 plain:"The snow-capped mountain on Israel’s northern edge, the highest in the region. The name is usually linked to the root cherem, “set apart” or “sacred,” a word also used for things devoted or banned, so perhaps “the sacred mountain.” Psalm 133:3 likens brotherly unity to “the dew of Hermon.”",
 bg:"Deuteronomy 3:9 says the Sidonians called it Sirion and the Amorites Shenir. In Psalm 89:12, Tabor and Hermon “rejoice in thy name.”"}),
ot2_tabor:OT2({name:"Tabor",forms:["Tabor"],resp:"TAY-bor",say:"tay bor",heb:"תָּבוֹר",tr:"Tavor",strong:"H8396",books:["ps"],
 plain:"A rounded mountain in lower Galilee that rises alone above the Jezreel Valley, where Deborah and Barak gathered their army (Judges 4:6, 12–14). The meaning of the name is uncertain. In Psalm 89:12, “The north and the south thou hast created them: Tabor and Hermon shall rejoice in thy name,” the two peaks stand for the whole land.",
 bg:""}),
// ================= Proverbs =================
ot2_agur:OT2({name:"Agur",forms:["Agur"],resp:"AY-gur",say:"ay gur",heb:"אָגוּר",tr:"ʾAgur",strong:"H94",books:["prov"],
 plain:"“The words of Agur the son of Jakeh” (30:1), the author of Proverbs 30, who is otherwise unknown. The meaning of his name is uncertain; “gatherer” has been suggested. The KJV’s “even the prophecy” may instead be a place name, Massa (Genesis 25:14), which would make him a wise man from that Ishmaelite tribe.",
 bg:"He prays, “give me neither poverty nor riches; feed me with food convenient for me” (30:8)."}),
ot2_lemuel:OT2({name:"Lemuel",forms:["Lemuel"],resp:"LEM-yoo-el",say:"lem yoo el",heb:"לְמוּאֵל",tr:"Lemuʾel",strong:"H3927",books:["prov"],
 plain:"A king whose mother’s advice fills Proverbs 31:1–9, including “open thy mouth for the dumb” and “judge righteously” (31:8–9). The name means “belonging to God” or “devoted to God.” He is otherwise unknown; some Jewish tradition treats Lemuel as a nickname for Solomon, but the text does not say.",
 bg:""}),
ot2_ithiel:OT2({name:"Ithiel and Ucal",forms:["Ithiel","Ucal"],resp:"ITH-ee-el / YOO-kul",say:"ith ee el, yoo kull",heb:"אִיתִיאֵל / אֻכָל",tr:"ʾItiʾel / ʾUkhal",strong:"H384 / H401",books:["prov"],
 plain:"The two men Agur addresses in 30:1, “even unto Ithiel and Ucal.” If they are names, Ithiel means “God is with me” and Ucal “I am able” or “I can prevail.” But the Hebrew can also be read without names, as “I am weary, O God; I am weary, O God, and am consumed,” which many modern versions prefer.",
 bg:""}),
// ================= Ecclesiastes =================
ot2_preacher:OT2({name:"Preacher (Qoheleth)",forms:["Preacher"],resp:"KO-HEL-eth",say:"ko hell eth",heb:"קֹהֶלֶת",tr:"Qohelet",strong:"H6953",books:["eccl"],
 plain:"The KJV’s word for the Hebrew Qoheleth, the speaker of the book: “The words of the Preacher, the son of David, king in Jerusalem” (1:1). It comes from qahal, “assembly,” so it means one who gathers or addresses an assembly, a teacher or gatherer of wisdom. The Greek title Ecclesiastes comes from the same idea (ekklesia, “assembly”).",
 bg:"Jewish and Christian tradition took him to be Solomon, though the book never names him."}),
ot2_vanity:OT2({name:"vanity (hevel)",forms:["vanity","vanities"],resp:"HEH-vel",say:"heh vell",heb:"הֶבֶל",tr:"hevel",strong:"H1892",books:["eccl"],
 plain:"The KJV’s word for Hebrew hevel, which literally means “breath” or “vapor,” something light that vanishes. The Preacher uses it more than thirty times (“Vanity of vanities; all is vanity,” 1:2) to say that life is fleeting and cannot be grasped, more than that it is worthless. “Vanity of vanities” is a Hebrew way of saying the most vapor-like of vapors.",
 bg:"Hevel is exactly the name Abel (Genesis 4:2), whose short life was a breath that vanished."}),
// ================= Song of Solomon =================
ot2_shulamite:OT2({name:"Shulamite",forms:["Shulamite"],resp:"SHOO-luh-mite",say:"shoo luh mite",heb:"הַשּׁוּלַמִּית",tr:"ha-Shulammit",strong:"H7759",books:["song"],
 plain:"What the chorus calls the bride in Song of Solomon 6:13: “Return, return, O Shulamite.” The word is used nowhere else, and its meaning is uncertain: it may be the feminine of Solomon (Shelomoh), “Solomon’s woman,” or “the peaceful one” from shalom, or mean a woman of Shunem, a town in Issachar.",
 bg:"The verse asks, “What will ye see in the Shulamite? As it were the company of two armies.”"}),
ot2_sharon:OT2({name:"Sharon",forms:["Sharon"],resp:"SHAIR-un",say:"shair un",heb:"שָׁרוֹן",tr:"Sharon",strong:"H8289",books:["song"],
 plain:"The fertile coastal plain between Joppa and Mount Carmel, known for flowers and pasture. The name is usually connected with a word for “level” or “plain.” The “rose of Sharon” (2:1) is a flower whose identity is uncertain; crocus, narcissus and lily have all been proposed.",
 bg:"Isaiah promises that “the excellency of Carmel and Sharon” will be given to the desert (Isaiah 35:2)."}),
ot2_lebanon:OT2({name:"Lebanon",forms:["Lebanon"],resp:"LEB-uh-nun",say:"leb uh nun",heb:"לְבָנוֹן",tr:"Levanon",strong:"H3844",books:["2chr","ps","song"],
 plain:"The mountain range north of Israel, famous for tall cedars, fragrant woods and cold streams. The name comes from laban, “white,” probably for its snowy peaks or pale limestone. The Song of Solomon draws on all of these: its fragrance (4:11), its streams (4:15), its cedar wood (3:9).",
 bg:"Solomon imported Lebanon’s cedar for the temple through Hiram of Tyre (2 Chronicles 2:8–16), and “the righteous … shall grow like a cedar in Lebanon” (Psalm 92:12)."}),
ot2_engedi:OT2({name:"En-gedi",forms:["En-gedi"],resp:"en-GED-eye",say:"en ged eye",heb:"עֵין גֶּדִי",tr:"ʿEin Gedi",strong:"H5872",books:["2chr","song"],
 plain:"An oasis on the western shore of the Dead Sea, watered by a freshwater spring in a barren desert. The name means “spring of the kid” (young goat). In 2 Chronicles 20:2 an invading army gathers at “Hazazon-tamar, which is En-gedi,” and in the Song of Solomon 1:14 the beloved is “a cluster of camphire in the vineyards of En-gedi.”",
 bg:"David hid from Saul in the wilderness of En-gedi (1 Samuel 24:1)."}),
ot2_tirzah:OT2({name:"Tirzah",forms:["Tirzah"],resp:"TUR-zuh",say:"tur zuh",heb:"תִּרְצָה",tr:"Tirtsah",strong:"H8656",books:["song"],
 plain:"In Song of Solomon 6:4 the beloved is “beautiful, O my love, as Tirzah, comely as Jerusalem.” Tirzah was a Canaanite city and the early capital of the northern kingdom until Omri moved it to Samaria (1 Kings 14:17; 16:23–24). The name comes from a root meaning “be pleasing,” so the comparison is also a pun on “delightful.”",
 bg:"Tirzah is also a woman’s name, one of the daughters of Zelophehad (Numbers 26:33)."}),
ot2_kedar:OT2({name:"Kedar",forms:["Kedar"],resp:"KEE-dar",say:"kee dar",heb:"קֵדָר",tr:"Qedar",strong:"H6938",books:["1chr","ps","song"],
 plain:"A son of Ishmael (1:29) and the Arabian nomad tribe descended from him, known for black goat-hair tents and flocks. The name is usually linked to a root meaning “dark” or “black,” which sharpens the Song of Solomon’s line: “I am black, but comely, … as the tents of Kedar” (1:5).",
 bg:"The psalmist laments, “Woe is me, that I sojourn in Mesech, that I dwell in the tents of Kedar!” (Psalm 120:5)."})
});

